    private string GetStarRating()
    {
        var filled = Math.Clamp((int)Math.Round(Product.Rating), 0, 5);
        return new string('★', filled) + new string('☆', 5 - filled);
    }

    private async Task HandleCardClick() => await OnSelected.InvokeAsync(Product);

    private async Task HandleAddToCartClick() => await OnAddToCart.InvokeAsync(Product);
}
"}

