    <div class="product-image-placeholder d-flex align-items-center justify-content-center bg-light"
         role="img" aria-label="@Product.Name" style="height: 180px;">
        <span class="text-muted small text-center px-2">@Product.Name</span>
    </div>
    <div class="card-body d-flex flex-column">
        <h5 class="card-title">@Product.Name</h5>
        <p class="card-text fw-bold text-primary mb-1">@Product.Price.ToString("C")</p>
        <p class="card-text mb-2">
            <span class="text-warning" aria-label="@($"Rating: {Product.Rating:F1} out of 5")">@GetStarRating()</span>
        </p>
        @if (!Product.InStock)
        {
            <span class="badge bg-danger mb-2 align-self-start">Out of Stock</span>
        }
        <button class="btn btn-primary mt-auto"
                disabled="@(!Product.InStock)"
                @onclick="HandleAddToCartClick"
                @onclick:stopPropagation>
            Add to Cart
        </button>
    </div>
</div>

