@if (TotalPages > 1)
{
    <nav aria-label="Product catalog pagination">
        <ul class="pagination justify-content-center mt-4 mb-0">
            <li class="page-item @(CurrentPage <= 1 ? "disabled" : "")">
                <button class="page-link" disabled="@(CurrentPage <= 1)"
                        @onclick="() => OnPageChanged.InvokeAsync(CurrentPage - 1)">
                    Previous
                </button>
            </li>
            @for (var i = 1; i <= TotalPages; i++)
            {
                var pageNum = i;
                <li class="page-item @(pageNum == CurrentPage ? "active" : "")">
                    <button class="page-link" @onclick="() => OnPageChanged.InvokeAsync(pageNum)">
                        @pageNum
                    </button>
                </li>
            }
            <li class="page-item @(CurrentPage >= TotalPages ? "disabled" : "")">
                <button class="page-link" disabled="@(CurrentPage >= TotalPages)"
                        @onclick="() => OnPageChanged.InvokeAsync(CurrentPage + 1)">
                    Next
                </button>
            </li>
        </ul>
    </nav>
}

