@@ -1,0 +1,154 @@
+@page "/catalog"
+@rendermode InteractiveServer
+@inject IProductService ProductService
+
+<PageTitle>Product Catalog</PageTitle>
+
+<h1 class="mb-4">Product Catalog</h1>
+
+<div class="d-flex gap-4">
+    <aside class="catalog-sidebar border rounded bg-white" style="min-width: 250px; flex: 0 0 25%;">
+        <CatalogFilterPanel Categories="categories" OnFilterApplied="HandleFilterApplied" />
+    </aside>
+
+    <main class="flex-grow-1">
+        @if (isLoading)
+        {
+            <div class="d-flex justify-content-center align-items-center p-5">
+                <div class="spinner-border text-primary" role="status">
+                    <span class="visually-hidden">Loading products…</span>
+                </div>
+            </div>
+        }
+        else if (errorMessage is not null)
+        {
+            <div class="alert alert-danger" role="alert">
+                <strong>Error:</strong> @errorMessage
+                <button class="btn btn-sm btn-outline-danger ms-3" @onclick="RetrySearch">Retry</button>
+            </div>
+        }
+        else if (result is { Items.Count: 0 })
+        {
+            <div class="alert alert-info" role="status">
+                No products match your current filters. Try adjusting your criteria.
+            </div>
+        }
+        else if (result is not null)
+        {
+            <div class="d-flex justify-content-between align-items-center mb-3 flex-wrap gap-2">
+                <div>
+                    <label class="form-label mb-0 me-2 fw-bold" for="sortSelect">Sort by:</label>
+                    <select id="sortSelect" class="form-select form-select-sm d-inline-block w-auto"
+                            @bind="sortBy" @bind:after="HandleSortChanged">
+                        <option value="price_asc">Price: Low to High</option>
+                        <option value="price_desc">Price: High to Low</option>
+                        <option value="name_asc">Name: A–Z</option>
+                        <option value="rating_desc">Rating: Highest</option>
+                    </select>
+                </div>
+                <span class="text-muted">
+                    Showing @rangeStart–@rangeEnd of @result.TotalCount products
+                </span>
+            </div>
+
+            <div class="row row-cols-1 row-cols-sm-2 row-cols-lg-3 row-cols-xl-4 g-3">
+                @foreach (var product in result.Items)
+                {
+                    <div class="col">
+                        <ProductCard Product="product"
+                                     OnSelected="HandleProductSelected"
+                                     OnAddToCart="HandleAddToCart" />
+                    </div>
+                }
+            </div>
+
+            <CatalogPagination CurrentPage="result.Page"
+                               TotalPages="totalPages"
+                               OnPageChanged="HandlePageChanged" />
+        }
+    </main>
+</div>
+
+@code {
+    private const int PageSize = 8;
+
+    private List<string>? categories;
+    private PagedResult<Product>? result;
+    private ProductFilter currentFilter = new(null, null, null, false);
+    private string sortBy = "price_asc";
+    private bool isLoading = true;
+    private string? errorMessage;
+
+    private int totalPages => result is null or { TotalCount: 0 }
+        ? 0
+        : (int)Math.Ceiling((double)result.TotalCount / result.PageSize);
+
+    private int rangeStart => result is null ? 0 : (result.Page - 1) * result.PageSize + 1;
+
+    private int rangeEnd => result is null
+        ? 0
+        : Math.Min(result.Page * result.PageSize, result.TotalCount);
+
+    [Parameter]
+    public EventCallback<Product> OnProductSelected { get; set; }
+
+    protected override async Task OnInitializedAsync()
+    {
+        await LoadCategoriesAsync();
+        await SearchAsync(page: 1);
+    }
+
+    private async Task LoadCategoriesAsync()
+    {
+        try
+        {
+            categories = await ProductService.GetCategoriesAsync();
+        }
+        catch
+        {
+            categories = [];
+        }
+    }
+
+    private async Task SearchAsync(int page)
+    {
+        isLoading = true;
+        errorMessage = null;
+
+        try
+        {
+            result = await ProductService.SearchAsync(currentFilter, sortBy, page, PageSize);
+        }
+        catch (Exception ex)
+        {
+            errorMessage = ex.Message;
+            result = null;
+        }
+        finally
+        {
+            isLoading = false;
+        }
+    }
+
+    private async Task HandleFilterApplied(ProductFilter filter)
+    {
+        currentFilter = filter;
+        await SearchAsync(page: 1);
+    }
+
+    private async Task HandleSortChanged() => await SearchAsync(page: 1);
+
+    private async Task HandlePageChanged(int page) => await SearchAsync(page);
+
+    private async Task RetrySearch() => await SearchAsync(result?.Page ?? 1);
+
+    private async Task HandleProductSelected(Product product)
+        => await OnProductSelected.InvokeAsync(product);
+
+    private Task HandleAddToCart(Product product)
+    {
+        // Placeholder for cart integration
+        return Task.CompletedTask;
+    }
+}
+

